		id          string
		fingerprint string
		snap        string
		outcome     PutOutcome
		err         error
	}
	resultCh := make(chan result, instances)
	start := make(chan struct{})
	var wg sync.WaitGroup
	for i, st := range stores {
		wg.Add(1)
		go func(instance int, st *Store) {
			defer wg.Done()
			<-start
			fingerprint := fmt.Sprintf("fp-%d", instance)
