	}
	if replayedCount != 0 {
		t.Fatalf("replayed count = %d, want 0 for distinct fingerprints", replayedCount)
	}
	if conflictCount != instances-1 {
		t.Fatalf("conflict count = %d, want %d", conflictCount, instances-1)
	}

