	// see 503 storage_unavailable, never 409.
	if err := st.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	conflict := doJSON(t, handler, http.MethodPost, "/v1/idempotency/records", submitBody("k", "fp2", `{}`, ""))
