		!strings.HasPrefix(conflict.Body.String(), `{"error":{"code":"storage_unavailable",`) {
		t.Fatalf("conflict with failed event storage = %d %s, want 503 storage_unavailable",
			conflict.Code, conflict.Body.String())
	}
}
GOEOF
